'use client';

import { useState } from 'react';
import { useUserProfile } from '@/lib/hooks/useUserProfile';
import { AgeRange, StylePreference } from '@/lib/types/user-profile-types';
import { OnboardingWelcome } from './OnboardingWelcome';
import { OnboardingName } from './OnboardingName';
import { OnboardingDepartment } from './OnboardingDepartment';
import { OnboardingAge } from './OnboardingAge';
import { OnboardingStyle } from './OnboardingStyle';
import { OnboardingPhoto } from './OnboardingPhoto';
import { OnboardingComplete } from './OnboardingComplete';

interface OnboardingFlowProps {
  onComplete: () => void;
}

export function OnboardingFlow({ onComplete }: OnboardingFlowProps) {
  const [currentStep, setCurrentStep] = useState(1);
  const { profile, updateProfile, completeOnboarding } = useUserProfile();

  const handleNext = () => {
    setCurrentStep((prev) => prev + 1);
  };

  const handleBack = () => {
    setCurrentStep((prev) => Math.max(1, prev - 1));
  };

  const handleNameSubmit = (name: string) => {
    updateProfile({ userName: name });
    handleNext();
  };

  const handleDepartmentSubmit = () => {
    updateProfile({ gender: 'women' });
    handleNext();
  };

  const handleAgeSubmit = (ageRange: AgeRange) => {
    updateProfile({ ageRange });
    handleNext();
  };

  const handleStyleSubmit = (styles: StylePreference[]) => {
    updateProfile({ stylePreferences: styles });
    handleNext();
  };

  const handlePhotoSubmit = (photoData?: string) => {
    updateProfile({ userPhoto: photoData });
    handleNext();
  };

  const handleComplete = () => {
    completeOnboarding();
    onComplete();
  };

  return (
    <div className="onboarding-container">
      {currentStep === 1 && <OnboardingWelcome onNext={handleNext} />}

      {currentStep === 2 && (
        <OnboardingName onNext={handleNameSubmit} onBack={handleBack} />
      )}

      {currentStep === 3 && (
        <OnboardingDepartment onNext={handleDepartmentSubmit} onBack={handleBack} />
      )}

      {currentStep === 4 && (
        <OnboardingAge onNext={handleAgeSubmit} onBack={handleBack} />
      )}

      {currentStep === 5 && (
        <OnboardingStyle onNext={handleStyleSubmit} onBack={handleBack} />
      )}

      {currentStep === 6 && (
        <OnboardingPhoto onNext={handlePhotoSubmit} onBack={handleBack} />
      )}

      {currentStep === 7 && profile && (
        <OnboardingComplete profile={profile} onComplete={handleComplete} />
      )}
    </div>
  );
}

import { generateOutfits } from '@/lib/outfit-generator'
import type { Outfit, Product, FilterState } from '@/lib/types'

export async function fetchOutfits(
  products: Product[],
  filters?: FilterState,
  count: number = 50
): Promise<Outfit[]> {
  try {
    // Filter products by gender
    let filteredProducts = products
    if (filters?.gender && filters.gender !== 'all') {
      filteredProducts = products.filter(
        p => p.category?.toLowerCase() === filters.gender
      )
    }

    console.log('[OutfitService] Filtered products:', filteredProducts.length)
    console.log('[OutfitService] Filters:', filters)

    // Determine style from occasion filter
    const style = filters?.occasion?.[0] as any || 'any'

    // Generate outfits using Story 1.5 logic
    const outfits = generateOutfits(filteredProducts, {
      count,
      style,
      gender: filters?.gender !== 'all' ? filters?.gender : undefined,
      priceRange: filters?.priceRange
    })

    console.log('[OutfitService] Outfits generated:', outfits.length)
    console.log('[OutfitService] Sample outfit:', outfits[0])
    console.log('[OutfitService] All outfits have imageUrl:', outfits.every(o => o.imageUrl))

    return outfits
  } catch (error) {
    console.error('Failed to generate outfits:', error)
    throw new Error('Outfit generation failed')
  }
}

export async function loadProducts(): Promise<Product[]> {
  try {
    const response = await fetch('/api/products')
    if (!response.ok) {
      throw new Error('Failed to load products')
    }
    const data = await response.json()
    const products = data.products || []

    // Debug: Log product data flow
    console.log('[ProductService] Products loaded:', products.length)
    console.log('[ProductService] Sample product:', products[0])
    console.log('[ProductService] All products have imageUrl:', products.every((p: Product) => p.imageUrl))

    return products
  } catch (error) {
    console.error('Failed to load products:', error)
    throw new Error('Product loading failed')
  }
}

/**
 * Data Loader
 * Loads and transforms product data from API to EnhancedProduct format
 */

import type { Product } from './types'
import type { EnhancedProduct } from './types/product-types'
import { transformCentralProduct } from './transformers/central-to-product'
import { enrichProductData } from './transformers/product-enrichment'
import { validateProduct } from './validation/product-validator'
import { setEnhancedProductCatalog, setProductCatalog } from './product-data'

/**
 * Load products from API and transform to EnhancedProduct format
 */
export async function loadEnhancedProducts(): Promise<EnhancedProduct[]> {
  try {
    // Determine the correct URL based on context
    const url = typeof window !== 'undefined'
      ? '/api/products' // Client-side: relative URL
      : `http://localhost:${process.env.PORT || 3002}/api/products` // Server-side: absolute URL

    // Fetch products from API
    const response = await fetch(url, {
      cache: 'force-cache',
    })

    if (!response.ok) {
      console.error('Failed to load products:', response.statusText)
      return []
    }

    const data = await response.json()
    const products: Product[] = data.products || []

    console.log(`[DataLoader] Loaded ${products.length} products from API`)

    // Transform to EnhancedProduct format
    const enhancedProducts: EnhancedProduct[] = []

    for (const product of products) {
      try {
        // Create scraped product structure
        const scrapedProduct = {
          product_name: product.name,
          product_desc: '',
          product_link: product.onlineUrl || '',
          product_size: product.sizes?.join(', ') || '',
          product_price: `฿${product.price.toLocaleString()}`,
          product_image: product.imageUrl,
        }

        // Detect gender from category
        const gender = product.category?.toLowerCase().includes('women')
          ? 'women'
          : product.category?.toLowerCase().includes('men')
            ? 'men'
            : undefined

        // Transform to enhanced format
        let transformed = transformCentralProduct(scrapedProduct, {
          gender,
        })

        // Enrich with inferred attributes
        transformed = enrichProductData(transformed)

        // Validate
        const validation = validateProduct(transformed)

        if (validation.valid && transformed.id && transformed.sku) {
          enhancedProducts.push(transformed as EnhancedProduct)
        } else {
          console.warn(`[DataLoader] Invalid product skipped: ${product.name}`, validation.errors)
        }
      } catch (error) {
        console.error(`[DataLoader] Error transforming product ${product.name}:`, error)
      }
    }

    console.log(`[DataLoader] Successfully transformed ${enhancedProducts.length} products to EnhancedProduct format`)

    // Update global catalogs
    setProductCatalog(products)
    setEnhancedProductCatalog(enhancedProducts)

    return enhancedProducts
  } catch (error) {
    console.error('[DataLoader] Error loading enhanced products:', error)
    return []
  }
}

/**
 * Initialize product catalog on app startup
 */
export async function initializeProductCatalog(): Promise<{
  legacy: Product[]
  enhanced: EnhancedProduct[]
}> {
  try {
    console.log('[DataLoader] Initializing product catalog...')

    // Load and transform products
    const enhanced = await loadEnhancedProducts()

    // Determine the correct URL based on context
    const url = typeof window !== 'undefined'
      ? '/api/products' // Client-side: relative URL
      : `http://localhost:${process.env.PORT || 3002}/api/products` // Server-side: absolute URL

    // Fetch legacy products
    const response = await fetch(url, {
      cache: 'force-cache',
    })

    const data = await response.json()
    const legacy: Product[] = data.products || []

    console.log(
      `[DataLoader] Catalog initialized: ${legacy.length} legacy products, ${enhanced.length} enhanced products`
    )

    return {
      legacy,
      enhanced,
    }
  } catch (error) {
    console.error('[DataLoader] Failed to initialize product catalog:', error)
    return {
      legacy: [],
      enhanced: [],
    }
  }
}

"use client"

import { useState, useEffect } from "react"
import ChatInterface from "@/components/chat/ChatInterface"
import OutfitDetails from "@/components/outfit/OutfitDetails"
import { Button } from "@/components/ui/button"
import { NavigationFilters } from "@/components/navigation/NavigationFilters"
import { OutfitDiscovery } from "@/components/outfit/OutfitDiscovery"
import { ChatAssistant } from "@/components/chat/ChatAssistant"
import { OutfitDetail } from "@/components/outfit/OutfitDetail"
import { ResizablePanel } from "@/components/layout/ResizablePanel"
import { useOutfitDiscovery } from "@/lib/hooks/useOutfitDiscovery"
import { useOutfitCache } from "@/lib/hooks/useOutfitCache"
import { loadProducts, fetchOutfits } from "@/lib/services/outfit-service"
import type { Product, Outfit } from "@/lib/types"
import { getGenderSpecificUrl, getSimilarOutfits } from "@/lib/utils/product-utils"
import { initializeProductCatalog } from "@/lib/data-loader"
import { MessageCircle, Sparkles, Bell, SlidersHorizontal, Grid3x3 } from "lucide-react"
import { OnboardingFlow } from "@/components/onboarding/OnboardingFlow"
import { useUserProfile } from "@/lib/hooks/useUserProfile"

export default function HomePage() {
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null)
  const [isOutfitDetailsOpen, setIsOutfitDetailsOpen] = useState(false)
  const [activeTab, setActiveTab] = useState<"outfits" | "chat" | "filters">("outfits")
  const [products, setProducts] = useState<Product[]>([])
  const [allOutfits, setAllOutfits] = useState<Outfit[]>([])
  const [isLoadingProducts, setIsLoadingProducts] = useState(true)
  const [isLoadingOutfits, setIsLoadingOutfits] = useState(false)
  const [showOnboarding, setShowOnboarding] = useState(true)

  // User profile hook for onboarding
  const { profile, isLoading: isLoadingProfile } = useUserProfile()

  // Cache hook
  const { getFromCache, saveToCache } = useOutfitCache()

  // Check onboarding status after profile loads
  useEffect(() => {
    if (!isLoadingProfile) {
      // Only hide onboarding if profile exists AND onboarding is completed
      if (profile?.onboardingCompleted) {
        setShowOnboarding(false)
      }
      // If no profile or onboarding not completed, keep showOnboarding as true
    }
  }, [profile, isLoadingProfile])

  // Handle onboarding completion
  const handleOnboardingComplete = () => {
    setShowOnboarding(false)
  }

  // Load products on mount
  useEffect(() => {
    // Initialize product catalog (loads both legacy and enhanced products)
    initializeProductCatalog()
      .then(({ legacy, enhanced }) => {
        console.log(`[HomePage] Loaded ${legacy.length} legacy products, ${enhanced.length} enhanced products`)
        setProducts(legacy)
      })
      .catch(err => {
        console.error('Failed to load products:', err)
        // Fallback to old loadProducts method
        loadProducts()
          .then(setProducts)
          .catch(() => console.error('Failed to load products'))
      })
      .finally(() => setIsLoadingProducts(false))
  }, [])

  // Use centralized outfit discovery hook
  const {
    filters,
    setFilters,
    filteredOutfits,
    selectedOutfit,
    viewMode,
    selectOutfit,
    backToChat,
    resetFilters
  } = useOutfitDiscovery(allOutfits)

  // Generate outfits when products load or filters change
  useEffect(() => {
    if (products.length === 0) return

    // Check cache first
    const cached = getFromCache(filters)
    if (cached && cached.length > 0) {
      setAllOutfits(cached)
      return
    }

    setIsLoadingOutfits(true)

    fetchOutfits(products, filters, 50)
      .then(outfits => {
        setAllOutfits(outfits)
        saveToCache(filters, outfits)
      })
      .catch(err => {
        console.error('Failed to generate outfits:', err)
      })
      .finally(() => setIsLoadingOutfits(false))
  }, [products, filters, getFromCache, saveToCache])

  // Keyboard navigation support
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // ESC key to close product detail or outfit details
      if (e.key === "Escape") {
        if (selectedProduct) {
          setSelectedProduct(null)
        } else if (selectedOutfit) {
          backToChat()
        }
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [selectedProduct, selectedOutfit, backToChat])

  const handleProductClick = (product: Product) => {
    setSelectedProduct(product)
  }

  const handleShopLook = (outfit: Outfit) => {
    console.log("Shopping for outfit:", outfit.title)
  }

  const handleBuyProduct = (product: Product) => {
    const url = getGenderSpecificUrl(product)
    window.open(url, '_blank', 'noopener,noreferrer')
  }

  const handleBuyAll = () => {
    if (!selectedOutfit) return
    // Open first product's URL as default
    const firstProduct = selectedOutfit.items[0]
    if (firstProduct) {
      handleBuyProduct(firstProduct)
    }
  }

  const getSimilarOutfitsForSelected = (): Outfit[] => {
    if (!selectedOutfit) return []
    return getSimilarOutfits(selectedOutfit, filteredOutfits, 6)
  }

  // Desktop three-panel layout
  const renderDesktopLayout = () => (
    // Full-width responsive layout that expands to fill the viewport
    // - Left Panel: Fixed 280px width for consistent navigation experience
    // - Middle Panel: Flexible (flex-1) to take remaining space
    // - Right Panel: Fixed 420px width for chat/details
    // This ensures the layout always fills 100% viewport width without max-width constraints

    <div className="hidden lg:flex h-screen w-full">
      {/* Left Panel - Navigation & Filters */}
      <div className="w-[280px] flex-shrink-0">
        <NavigationFilters
          filters={filters}
          onFilterChange={setFilters}
          onResetFilters={resetFilters}
        />
      </div>

      {/* Middle Panel - Outfit Discovery (Flexible, takes remaining space) */}
      <main className="flex-1 min-w-0" aria-label="Outfit Recommendations">
        <OutfitDiscovery
          outfits={filteredOutfits}
          onSelectOutfit={selectOutfit}
          onClearFilters={resetFilters}
          isLoading={isLoadingProducts || isLoadingOutfits}
        />
      </main>

      {/* Right Panel - Resizable Chat Assistant + Details */}
      <ResizablePanel
        defaultWidth={420}
        minWidth={280}
        maxWidthPercent={50}
        className="border-l"
        ariaLabel="Chat and outfit details"
      >
        {viewMode === "detail" && selectedOutfit ? (
          <OutfitDetail
            outfit={selectedOutfit}
            similarOutfits={getSimilarOutfitsForSelected()}
            onBack={backToChat}
            onBuyProduct={handleBuyProduct}
            onBuyAll={handleBuyAll}
            onSelectSimilar={selectOutfit}
          />
        ) : (
          <ChatAssistant onViewOutfit={selectOutfit} />
        )}
      </ResizablePanel>
    </div>
  )

  // Mobile layout with bottom tabs
  const renderMobileLayout = () => (
    <div className="lg:hidden flex flex-col h-screen">
      {/* Header */}
      <header className="sticky top-0 z-header border-b bg-background">
        <div className="flex items-center justify-between px-5 py-4">
          <div className="flex items-center gap-3">
            <Sparkles className="w-7 h-7 text-primary" />
            <h1 className="text-xl font-bold">OOTDay</h1>
          </div>
          <Button variant="ghost" size="sm" className="h-10 w-10">
            <Bell className="w-5 h-5" />
          </Button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        {activeTab === "outfits" && (
          <div className="p-5">
            <div className="grid grid-cols-2 gap-4">
              {filteredOutfits.map((outfit) => (
                <div
                  key={outfit.id}
                  className="cursor-pointer hover:shadow-lg transition-shadow border rounded-lg overflow-hidden"
                  onClick={() => selectOutfit(outfit)}
                >
                  <div className="aspect-[3/4] bg-gray-100"></div>
                  <div className="p-3">
                    <h3 className="font-medium text-sm line-clamp-1">{outfit.title}</h3>
                    <p className="text-primary font-bold text-sm mt-1">฿{outfit.totalPrice.toLocaleString()}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === "chat" && (
          <ChatInterface
            onOutfitSelect={(outfitId) => {
              const outfit = allOutfits.find(o => o.id === outfitId)
              if (outfit) selectOutfit(outfit)
            }}
            onViewDetails={selectOutfit}
          />
        )}

        {activeTab === "filters" && (
          <NavigationFilters
            filters={filters}
            onFilterChange={setFilters}
            onResetFilters={resetFilters}
          />
        )}
      </main>

      {/* Bottom Navigation */}
      <nav className="border-t bg-background">
        <div className="flex items-center justify-around py-3">
          <Button
            variant="ghost"
            size="sm"
            className={`flex flex-col items-center gap-1.5 h-auto py-2 ${
              activeTab === "filters" ? "text-primary" : "text-gray-600"
            }`}
            onClick={() => setActiveTab("filters")}
          >
            <SlidersHorizontal className="w-6 h-6" />
            <span className="text-xs font-medium">กรอง</span>
          </Button>

          <Button
            variant="ghost"
            size="sm"
            className={`flex flex-col items-center gap-1.5 h-auto py-2 ${
              activeTab === "outfits" ? "text-primary" : "text-gray-600"
            }`}
            onClick={() => setActiveTab("outfits")}
          >
            <Grid3x3 className="w-6 h-6" />
            <span className="text-xs font-medium">ชุด</span>
          </Button>

          <Button
            variant="ghost"
            size="sm"
            className={`flex flex-col items-center gap-1.5 h-auto py-2 ${
              activeTab === "chat" ? "text-primary" : "text-gray-600"
            }`}
            onClick={() => setActiveTab("chat")}
          >
            <MessageCircle className="w-6 h-6" />
            <span className="text-xs font-medium">แชท</span>
          </Button>
        </div>
      </nav>
    </div>
  )

  // Show loading state while profile is being loaded
  if (isLoadingProfile) {
    return null // or a loading spinner if desired
  }

  // Show onboarding if user hasn't completed it
  if (showOnboarding) {
    return <OnboardingFlow onComplete={handleOnboardingComplete} />
  }

  // Show main app
  return (
    <>
      {renderDesktopLayout()}
      {renderMobileLayout()}

      {/* Outfit Details Modal - for mobile */}
      <OutfitDetails
        outfit={selectedOutfit}
        isOpen={isOutfitDetailsOpen}
        onClose={() => {
          setIsOutfitDetailsOpen(false)
          setSelectedOutfit(null)
        }}
        onProductClick={handleProductClick}
        onShopLook={handleShopLook}
      />
    </>
  )
}

