/**
 * User Profile Type Definitions for OOTDay Onboarding Flow
 */

/**
 * Style preference option with details
 */
export interface StylePreference {
  id: string;
  name: string;
  description: string;
  cardDescription?: string;
  imageUrl?: string;
  longDescription?: string;
}

/**
 * Age range options for user profile
 */
export type AgeRange = '<20' | '20-29' | '30-39' | '40+';

/**
 * Complete user profile captured during onboarding
 */
export interface UserProfile {
  userName: string;
  gender: 'women'; // Currently fixed to women-only
  ageRange: AgeRange;
  stylePreferences: StylePreference[];
  userPhoto?: string; // Base64 encoded image or undefined for mystery avatar
  onboardingCompleted: boolean;
  createdAt: string; // ISO date string
}

/**
 * Partial profile for incremental updates during onboarding
 */
export type PartialUserProfile = Partial<UserProfile>;

// TypeScript interfaces for OOTDay Fashion Assistant

// Export all new type definitions
export * from './types/enums'
export * from './types/localization-types'
export * from './types/product-types'

// Legacy interfaces maintained for backward compatibility
// These will gradually be replaced by EnhancedProduct
export interface OutfitRequest {
  query: string
  userId?: string
  context?: {
    occasion?: string
    weather?: string
    preferences?: string[]
  }
}

export interface OutfitResponse {
  outfits: Outfit[]
  conversationId: string
  suggestions: string[]
}

export interface Outfit {
  id: string
  title: string
  description: string
  totalPrice: number
  items: Product[]
  imageUrl?: string
}

/**
 * @deprecated Use EnhancedProduct from './types/product-types' instead
 * This interface is kept for backward compatibility
 */
export interface Product {
  sku: string
  name: string
  brand: string
  price: number
  imageUrl: string
  availability: "in_stock" | "low_stock" | "out_of_stock"
  storeLocations?: string[]
  onlineUrl?: string
  sizes?: string[]
  colors?: string[]
  category?: string // "Men", "Women", or other categories
}

export interface ChatMessage {
  id: string
  content: string
  sender: "user" | "assistant"
  timestamp: Date
  outfits?: Outfit[]
  /** Image URL for generated outfit visualization (v3.1) */
  imageUrl?: string
  /** Base64-encoded image data (v3.1) */
  imageBase64?: string
  /** Outfit description used for image generation (v3.1) */
  outfitDescription?: string
}

export interface ConversationStarter {
  id: string
  text: string
  category: string
}

export interface FilterState {
  gender?: 'all' | 'men' | 'women'
  occasion?: string[]  // ['work', 'casual', 'date', 'formal']
  priceRange?: { min: number; max: number }
  searchQuery?: string
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import { useSearchParams, useRouter, usePathname } from 'next/navigation'
import type { Outfit, FilterState } from '@/lib/types'
import { filterOutfits } from '@/lib/utils/outfit-filter'
import { parseFiltersFromUrl, filtersToUrlParams } from '@/lib/utils/url-params'

export function useOutfitDiscovery(allOutfits: Outfit[]) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  // Initialize state from URL
  const [filters, setFilters] = useState<FilterState>(() =>
    parseFiltersFromUrl(searchParams)
  )

  const [selectedOutfit, setSelectedOutfit] = useState<Outfit | null>(null)
  const [viewMode, setViewMode] = useState<'chat' | 'detail'>('chat')

  // Load selected outfit from URL on mount
  useEffect(() => {
    const outfitId = searchParams.get('outfit')
    if (outfitId) {
      const outfit = allOutfits.find(o => o.id === outfitId)
      if (outfit) {
        setSelectedOutfit(outfit)
        setViewMode('detail')
      }
    }
  }, []) // Run only on mount

  // Memoized filtered outfits
  const filteredOutfits = useMemo(() => {
    return filterOutfits(allOutfits, filters)
  }, [allOutfits, filters])

  // Sync URL with state (debounced to avoid excessive updates)
  useEffect(() => {
    const params = filtersToUrlParams(filters, selectedOutfit?.id)
    const newUrl = params ? `${pathname}?${params}` : pathname

    // Only update if URL actually changed
    const currentUrl = `${pathname}${searchParams.toString() ? '?' + searchParams.toString() : ''}`
    if (newUrl !== currentUrl) {
      window.history.pushState({}, '', newUrl)
    }
  }, [filters, selectedOutfit, pathname])

  // Handlers
  const selectOutfit = (outfit: Outfit) => {
    setSelectedOutfit(outfit)
    setViewMode('detail')
  }

  const backToChat = () => {
    setSelectedOutfit(null)
    setViewMode('chat')
  }

  const resetFilters = () => {
    setFilters({
      gender: 'all',
      occasion: [],
      priceRange: { min: 0, max: 20000 },
      searchQuery: ''
    })
  }

  return {
    filters,
    setFilters,
    filteredOutfits,
    selectedOutfit,
    viewMode,
    selectOutfit,
    backToChat,
    resetFilters
  }
}

